def load() -> pd.DataFrame:
    import cdflib
    cdf = cdflib.CDF('data/astronomy/input/swarm/SW_OPER_ACCACAL_2__20240511T000000_20240511T235959_0304.cdf')
    info = cdf.cdf_info()
    vars_list = info.zVariables
    data = {}
    for v in vars_list:
        try:
            val = cdf.varget(v)
            if val is not None and hasattr(val, '__len__'):
                if len(val.shape) == 1:
                    data[v] = val
                elif len(val.shape) == 2 and val.shape[1] <= 10:
                    for i in range(val.shape[1]):
                        data[f"{v}_{i}"] = val[:, i]
        except Exception:
            pass
    df = pd.DataFrame(data)
    return df

def process(swarm_hourly, parse_kp, parse_pdyn):
    # Merge all three on datetime
    df = swarm_hourly.merge(
        parse_kp[['datetime', 'Kp']], on='datetime', how='inner'
    ).merge(
        parse_pdyn[['datetime', 'Pdyn']], on='datetime', how='inner'
    )
    df = df.sort_values('datetime').reset_index(drop=True)
    return df
